import { useFieldContext } from '@ark-ui/vue/field';
import { useFieldsetContext } from '@ark-ui/vue/fieldset';
import {
  useSegmentGroup as useSegmentGroupPrimitive,
  type UseSegmentGroupProps,
  type UseSegmentGroupReturn,
} from '@ark-ui/vue/segment-group';
import { computed, toValue, unref } from 'vue';
import type { MaybeRef } from 'vue';

function omitUndefined<T extends object>(props: T) {
  return Object.fromEntries(Object.entries(props).filter(([, value]) => value !== undefined)) as T;
}

function normalizeBoolean(value: unknown) {
  return value === true || value === 'true'
    ? true
    : value === false || value === 'false'
      ? false
      : undefined;
}

const useSegmentGroup = (
  props: MaybeRef<UseSegmentGroupProps> = {},
  emit?: Parameters<typeof useSegmentGroupPrimitive>[1],
): UseSegmentGroupReturn => {
  const field = useFieldContext();
  const fieldset = useFieldsetContext();

  return useSegmentGroupPrimitive(
    computed<UseSegmentGroupProps>(() => ({
      orientation: 'horizontal' as const,
      disabled: normalizeBoolean(unref(field)?.disabled ?? unref(fieldset)?.disabled),
      invalid: normalizeBoolean(unref(field)?.invalid ?? unref(fieldset)?.invalid),
      readOnly: normalizeBoolean(unref(field)?.readOnly),
      required: normalizeBoolean(unref(field)?.required),
      ...omitUndefined(toValue(props) ?? {}),
    })),
    emit,
  );
};

export default useSegmentGroup;

@layer moduix.components {
  .root {
    box-sizing: border-box;
    position: relative;
    isolation: isolate;
    display: inline-flex;
    max-inline-size: var(--moduix-segment-group-max-width, 100%);
    align-items: stretch;
    gap: var(--moduix-segment-group-gap, var(--moduix-spacing-1));
    padding: var(--moduix-segment-group-padding, var(--moduix-spacing-1));
    border: var(--moduix-segment-group-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-segment-group-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-segment-group-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-segment-group-bg, var(--moduix-color-muted));
    color: var(--moduix-segment-group-color, var(--moduix-color-foreground));

    &[data-orientation='vertical'] {
      flex-direction: column;
      align-items: stretch;
    }

    &[data-disabled] {
      opacity: var(--moduix-segment-group-disabled-opacity, var(--moduix-opacity-disabled));
    }

    &:not([data-disabled]) {
      .item[data-disabled] {
        opacity: var(--moduix-segment-group-item-disabled-opacity, var(--moduix-opacity-disabled));
      }
    }

    &[data-invalid] {
      border-color: var(
        --moduix-segment-group-border-color-invalid,
        var(--moduix-color-destructive)
      );
    }
  }

  .label {
    position: relative;
    z-index: 1;
    color: var(
      --moduix-segment-group-label-color,
      var(--moduix-segment-group-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-segment-group-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-segment-group-label-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-segment-group-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
  }

  .item {
    box-sizing: border-box;
    position: relative;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-segment-group-item-gap, var(--moduix-spacing-2));
    min-height: var(--moduix-segment-group-item-height, var(--moduix-size-sm));
    border-radius: var(--moduix-segment-group-item-radius, var(--moduix-radius-md));
    padding-inline: var(--moduix-segment-group-item-padding-x, var(--moduix-spacing-3-5));
    color: var(--moduix-segment-group-item-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-segment-group-item-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-segment-group-item-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-segment-group-item-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
    white-space: nowrap;
    cursor: pointer;
    outline: 0;
    transition:
      color var(--moduix-segment-group-transition, var(--moduix-transition-default)),
      opacity var(--moduix-segment-group-transition, var(--moduix-transition-default));

    @media (hover: hover) {
      &:hover:not([data-readonly], [data-disabled]) {
        color: var(--moduix-segment-group-item-color-hover, var(--moduix-color-foreground));

        &[data-state='checked'] {
          color: var(
            --moduix-segment-group-item-color-hover,
            var(--moduix-segment-group-item-color-checked, var(--moduix-color-foreground))
          );
        }
      }
    }

    &[data-state='checked'] {
      color: var(--moduix-segment-group-item-color-checked, var(--moduix-color-foreground));
    }

    &[data-focus-visible] {
      outline: var(
          --moduix-segment-group-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-segment-group-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-segment-group-focus-ring-offset, var(--moduix-border-width-sm));
    }

    &[data-invalid][data-focus-visible] {
      outline-color: var(
        --moduix-segment-group-focus-ring-color-invalid,
        var(--moduix-color-destructive)
      );
    }

    &[data-readonly],
    &[data-disabled] {
      cursor: default;
    }

    &[data-orientation='vertical'] {
      inline-size: 100%;
      justify-content: flex-start;
    }
  }

  .itemControl {
    display: none;
  }

  .itemText {
    position: relative;
    z-index: 1;
  }

  .indicator {
    --transition-duration: var(
      --moduix-segment-group-indicator-transition-duration,
      var(--moduix-duration-normal)
    );
    --transition-timing-function: var(
      --moduix-segment-group-indicator-transition-timing-function,
      var(--moduix-ease-in-out)
    );

    position: absolute;
    z-index: 0;
    top: var(--top);
    left: var(--left);
    width: var(--width);
    height: var(--height);
    border-radius: var(--moduix-segment-group-indicator-radius, var(--moduix-radius-md));
    background-color: var(--moduix-segment-group-indicator-bg, var(--moduix-color-background));
    box-shadow: var(--moduix-segment-group-indicator-shadow, var(--moduix-shadow-sm));
    pointer-events: none;
  }
}

import { useSegmentGroupContext, useSegmentGroupItemContext } from '@ark-ui/vue/segment-group';
import SegmentGroup from './SegmentGroup.vue';
import SegmentGroupContext from './SegmentGroupContext.vue';
import SegmentGroupIndicator from './SegmentGroupIndicator.vue';
import SegmentGroupItem from './SegmentGroupItem.vue';
import SegmentGroupItemContext from './SegmentGroupItemContext.vue';
import SegmentGroupItemControl from './SegmentGroupItemControl.vue';
import SegmentGroupItemHiddenInput from './SegmentGroupItemHiddenInput.vue';
import SegmentGroupItems from './SegmentGroupItems.vue';
import SegmentGroupItemText from './SegmentGroupItemText.vue';
import SegmentGroupLabel from './SegmentGroupLabel.vue';
import SegmentGroupRootProvider from './SegmentGroupRootProvider.vue';
import useSegmentGroup from './useSegmentGroup';

export {
  SegmentGroup,
  SegmentGroupContext,
  SegmentGroupIndicator,
  SegmentGroupItem,
  SegmentGroupItemContext,
  SegmentGroupItemControl,
  SegmentGroupItemHiddenInput,
  SegmentGroupItems,
  SegmentGroupItemText,
  SegmentGroupLabel,
  SegmentGroupRootProvider,
  useSegmentGroup,
  useSegmentGroupContext,
  useSegmentGroupItemContext,
};

export type {
  SegmentGroupContextProps,
  SegmentGroupIndicatorProps,
  SegmentGroupItemContextProps,
  SegmentGroupItemHiddenInputProps,
  SegmentGroupItemProps,
  SegmentGroupItemTextProps,
  SegmentGroupLabelProps,
  SegmentGroupValueChangeDetails,
  UseSegmentGroupContext,
  UseSegmentGroupItemContext,
  UseSegmentGroupProps,
  UseSegmentGroupReturn,
} from '@ark-ui/vue/segment-group';

export type {
  Emits as SegmentGroupRootEmits,
  Props as SegmentGroupRootProps,
} from './SegmentGroup.vue';
export type { Props as SegmentGroupItemControlProps } from './SegmentGroupItemControl.vue';
export type {
  SegmentGroupItemOption,
  Props as SegmentGroupItemsProps,
} from './SegmentGroupItems.vue';
export type { Props as SegmentGroupRootProviderProps } from './SegmentGroupRootProvider.vue';
